const game = new GF.Game({
  id: 'lumen-current',
  title: 'Lumen Current',
  width: 960,
  height: 540,
  palette: ['#54F5D2', '#B9FF82', '#103447', '#071522'],
  background: '#071522',
  seed: 41291
});

/* Provide bounded evidence storage when the host does not expose its telemetry hook. */
if (typeof game.event !== 'function') {
  game._events = [];
  game.event = function(type, data) {
    if (this._events.length < 80) this._events.push({ type: String(type), data: data || {}, time: this.time });
    if (window.__GF__) window.__GF__.events = this._events;
  };
}

const C = {
  ink: '#071522', deep: '#103447', cyan: '#54F5D2', mint: '#B9FF82',
  violet: '#a982ff', glass: '#79cfe6', white: '#eafff8', storm: '#b878e8'
};

const play = {
  init() {
    this.motes = [];
    for (let i = 0; i < 52; i++) {
      this.motes.push({ x: game.rng() * 960, y: game.rng() * 540, r: 1 + game.rng() * 2, s: 8 + game.rng() * 22, p: game.rng() * 6.28 });
    }
    this.trail = Array.from({ length: 18 }, () => ({ x: 480, y: 270 }));
    this.didRun = false;
    this.terminalRun = false;
  },

  reset() {
    const freshAfterTerminal = this.terminalRun === true;
    this.player = { x: 480, y: 270, slow: 0, pulse: 0, px: 480, py: 270 };
    this.nodes = [
      { x: 780, y: 270, name: 'EAST GLASS', active: false, glow: 0 },
      { x: 850, y: 430, name: 'SOUTH REED', active: false, glow: 0 },
      { x: 395, y: 480, name: 'WEST VINE', active: false, glow: 0 }
    ];
    this.ribbons = [
      { x: 160, y: 120, vx: 1, phase: 0.4, hit: 0 },
      { x: 640, y: 175, vx: -1, phase: 2.1, hit: 0 },
      { x: 340, y: 375, vx: 1, phase: 4.3, hit: 0 }
    ];
    this.progress = 0;
    this.pressure = 0;
    this.hazardSpeed = 35;
    this.contactCd = 0;
    this.musicClock = 0;
    this.inputRecorded = false;
    this.guidance = 0;
    this.terminalRun = false;
    for (let i = 0; i < this.trail.length; i++) { this.trail[i].x = 480; this.trail[i].y = 270; }
    if (freshAfterTerminal) game.event('fresh_run_started', { nodeProgress: 0 });
    this.didRun = true;
  },

  resonate() {
    const p = this.player;
    p.pulse = 0.48;
    game.flash('#54F5D2', 0.11);
    game.burst(p.x, p.y, { count: 16, speed: 105, size: 3, life: 0.48, colors: [C.cyan, C.mint, C.white], gravity: 0 });
    GF.Sfx.beep({ freq: 430, to: 700, dur: 0.18, type: 'sine', vol: 0.16 });
    if (this.progress > 0 && this.inputRecorded) {
      game.event('movement_and_resonance_input', { x: Math.round(p.x), y: Math.round(p.y), resonance: 1 });
      this.inputRecorded = false;
    }
    for (let i = 0; i < this.nodes.length; i++) {
      const n = this.nodes[i];
      if (!n.active && Math.hypot(p.x - n.x, p.y - n.y) < 112) {
        this.activateNode(i);
        break;
      }
    }
  },

  activateNode(index) {
    const n = this.nodes[index];
    if (!n || n.active) return;
    const before = this.progress;
    n.active = true;
    n.glow = 1;
    this.progress++;
    const award = 100 * this.progress;
    game.addScore(award);
    game.event('signal_node_activated', {
      nodeProgressBefore: before,
      nodeProgressAfter: this.progress,
      scoreAward: award
    });
    const speedBefore = this.hazardSpeed;
    this.hazardSpeed += 18;
    game.event('pressure_escalated', { hazardSpeedBefore: speedBefore, hazardSpeedAfter: this.hazardSpeed });
    this.pressure = Math.max(0, this.pressure - 5);
    game.burst(n.x, n.y, { count: 38, speed: 180, size: 4, life: 0.9, colors: [C.cyan, C.mint, C.white], gravity: 26 });
    game.flash('#B9FF82', 0.20);
    game.hitStop(this.progress === 3 ? 0.13 : 0.09);
    game.shake(this.progress === 3 ? 6 : 3, 0.22);
    GF.Sfx.melody([[523, 0.09], [659, 0.11], [784, 0.18]], { type: 'triangle', vol: 0.2 });
    if (this.progress === 3) {
      this.terminalRun = true;
      game.burst(480, 270, { count: 70, speed: 260, size: 5, life: 1.2, colors: [C.cyan, C.mint, C.white], gravity: 12 });
      game.win({ message: 'GARDEN RESTORED' });
    }
  },

  update(dt) {
    const p = this.player;
    const k = game.input.keys;
    let dx = (k.ArrowRight || k.KeyD ? 1 : 0) - (k.ArrowLeft || k.KeyA ? 1 : 0);
    let dy = (k.ArrowDown || k.KeyS ? 1 : 0) - (k.ArrowUp || k.KeyW ? 1 : 0);
    if (dx || dy) {
      const l = Math.hypot(dx, dy) || 1;
      dx /= l; dy /= l;
      this.inputRecorded = true;
      const speed = p.slow > 0 ? 125 : 220;
      p.px = p.x; p.py = p.y;
      p.x = GF.math.clamp(p.x + dx * speed * dt, 42, 918);
      p.y = GF.math.clamp(p.y + dy * speed * dt, 78, 498);
    }
    if (game.input.pressed('Space') || game.input.pressed('Enter') || game.input.pointer.clicked) this.resonate();
    p.slow = Math.max(0, p.slow - dt);
    p.pulse = Math.max(0, p.pulse - dt);
    this.contactCd = Math.max(0, this.contactCd - dt);
    this.guidance += dt;

    for (let i = this.trail.length - 1; i > 0; i--) {
      this.trail[i].x += (this.trail[i - 1].x - this.trail[i].x) * Math.min(1, dt * 14);
      this.trail[i].y += (this.trail[i - 1].y - this.trail[i].y) * Math.min(1, dt * 14);
    }
    this.trail[0].x = p.x; this.trail[0].y = p.y;

    this.pressure = GF.math.clamp(this.pressure + dt * (1.12 + this.progress * 0.48), 0, 100);
    for (const r of this.ribbons) {
      r.x += r.vx * this.hazardSpeed * dt;
      if (r.x < -100) { r.x = 1060; r.vx = -1; }
      if (r.x > 1060) { r.x = -100; r.vx = 1; }
      r.hit = Math.max(0, r.hit - dt);
      const ry = r.y + Math.sin(game.time * (0.8 + this.progress * 0.12) + r.phase) * 42;
      if (this.contactCd <= 0 && Math.abs(p.x - r.x) < 32 && Math.abs(p.y - ry) < 58) {
        this.contactCd = 0.7; p.slow = 0.5; r.hit = 0.35;
        this.pressure = GF.math.clamp(this.pressure + 8, 0, 100);
        game.shake(4, 0.18);
        game.burst(p.x, p.y, { count: 12, speed: 95, size: 3, life: 0.36, colors: [C.violet, '#dfb8ff'], gravity: 0 });
        GF.Sfx.noise({ dur: 0.12, vol: 0.11, freq: 900 });
      }
    }
    for (const n of this.nodes) n.glow = Math.max(0, n.glow - dt * 0.65);
    this.musicClock += dt;
    if (this.musicClock > 3.6 - this.progress * 0.38) {
      this.musicClock = 0;
      GF.Sfx.beep({ freq: 180 + this.pressure * 1.2, to: 250 + this.progress * 70, dur: 0.16, type: 'sine', vol: 0.035 });
    }
    if (this.pressure >= 100) {
      this.terminalRun = true;
      game.flash('#a982ff', 0.28);
      game.gameOver({ message: 'STORM PRESSURE OVERLOAD' });
    }
  },

  draw(ctx) {
    const W = 960, H = 540, t = game.time;
    const bg = ctx.createLinearGradient(0, 0, W, H);
    bg.addColorStop(0, '#071522'); bg.addColorStop(0.55, '#0b2937'); bg.addColorStop(1, '#071522');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);

    ctx.globalAlpha = 0.13;
    for (let i = 0; i < 5; i++) {
      const x = ((i * 227 + t * (8 + i * 2)) % 1100) - 70;
      ctx.fillStyle = i % 2 ? C.glass : C.cyan;
      ctx.beginPath(); ctx.moveTo(x, 70); ctx.lineTo(x + 160, 70); ctx.lineTo(x + 90, 510); ctx.lineTo(x - 70, 510); ctx.fill();
    }
    ctx.globalAlpha = 1;

    ctx.strokeStyle = 'rgba(84,245,210,0.13)'; ctx.lineWidth = 1;
    for (let x = 60; x < 960; x += 90) { ctx.beginPath(); ctx.moveTo(x, 65); ctx.lineTo(x - 90, 510); ctx.stroke(); }
    for (const m of this.motes) {
      const y = (m.y + Math.sin(t * 0.7 + m.p) * 12 + t * m.s) % 520;
      ctx.globalAlpha = 0.22 + 0.18 * Math.sin(t + m.p);
      ctx.fillStyle = C.mint; ctx.beginPath(); ctx.arc(m.x, y, m.r, 0, GF.math.TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;

    for (let i = 0; i < this.nodes.length; i++) {
      const n = this.nodes[i];
      const next = i === this.progress;
      ctx.strokeStyle = n.active ? 'rgba(185,255,130,.62)' : next ? 'rgba(84,245,210,.62)' : 'rgba(84,245,210,.18)';
      ctx.lineWidth = n.active ? 4 : 2;
      ctx.beginPath(); ctx.moveTo(480, 270); ctx.quadraticCurveTo((480 + n.x) / 2, 270 + Math.sin(t + i) * 24, n.x, n.y); ctx.stroke();
      if (n.active) {
        ctx.fillStyle = 'rgba(84,245,210,.10)'; ctx.beginPath(); ctx.arc(n.x, n.y, 108, 0, GF.math.TAU); ctx.fill();
      }
    }

    for (const r of this.ribbons) {
      const y = r.y + Math.sin(t * (0.8 + this.progress * 0.12) + r.phase) * 42;
      const g = ctx.createLinearGradient(r.x - 52, y, r.x + 52, y);
      g.addColorStop(0, 'rgba(169,130,255,0)'); g.addColorStop(.5, 'rgba(184,120,232,.35)'); g.addColorStop(1, 'rgba(169,130,255,0)');
      ctx.fillStyle = g; ctx.fillRect(r.x - 65, y - 55, 130, 110);
      ctx.strokeStyle = 'rgba(218,174,255,.48)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(r.x - 46, y - 48); ctx.bezierCurveTo(r.x + 12, y - 22, r.x - 15, y + 19, r.x + 48, y + 48); ctx.stroke();
    }

    for (let i = 0; i < this.nodes.length; i++) {
      const n = this.nodes[i], next = i === this.progress;
      const pulse = next ? 1 + Math.sin(t * 4) * 0.08 : 1;
      ctx.globalAlpha = next || n.active ? 1 : 0.45;
      ctx.strokeStyle = n.active ? C.mint : C.cyan; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(n.x, n.y, (n.active ? 34 : 52) * pulse, 0, GF.math.TAU); ctx.stroke();
      ctx.fillStyle = n.active ? C.mint : C.cyan;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.active ? 12 : 15, 0, GF.math.TAU); ctx.fill();
      ctx.fillStyle = C.ink; ctx.beginPath(); ctx.arc(n.x, n.y, 5, 0, GF.math.TAU); ctx.fill();
      if (next) GF.Draw.text(ctx, 'NEXT SIGNAL', n.x, n.y - 72, { size: 13, color: C.mint, weight: '800' });
      ctx.globalAlpha = 1;
    }

    for (let i = this.trail.length - 1; i >= 0; i--) {
      const q = this.trail[i], a = (this.trail.length - i) / this.trail.length;
      ctx.globalAlpha = a * 0.42; ctx.fillStyle = C.cyan;
      ctx.beginPath(); ctx.arc(q.x, q.y, 3 + a * 7, 0, GF.math.TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;
    const p = this.player;
    if (p.pulse > 0) {
      ctx.globalAlpha = p.pulse / .48; ctx.strokeStyle = C.cyan; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(p.x, p.y, 28 + (1 - p.pulse / .48) * 86, 0, GF.math.TAU); ctx.stroke(); ctx.globalAlpha = 1;
    }
    const pg = ctx.createRadialGradient(p.x - 4, p.y - 5, 2, p.x, p.y, 27);
    pg.addColorStop(0, C.white); pg.addColorStop(.35, C.cyan); pg.addColorStop(1, 'rgba(84,245,210,0)');
    ctx.fillStyle = pg; ctx.beginPath(); ctx.arc(p.x, p.y, 28, 0, GF.math.TAU); ctx.fill();
    ctx.fillStyle = C.white; ctx.beginPath(); ctx.arc(p.x, p.y, 9, 0, GF.math.TAU); ctx.fill();

    this.drawHud(ctx);
    GF.Draw.vignette(ctx, W, H, 0.42);
  },

  drawHud(ctx) {
    GF.Draw.roundRect(ctx, 18, 15, 210, 47, 10, 'rgba(4,18,28,.80)');
    GF.Draw.text(ctx, 'SIGNALS', 31, 31, { size: 13, color: C.cyan, align: 'left', weight: '800' });
    for (let i = 0; i < 3; i++) {
      ctx.fillStyle = i < this.progress ? C.mint : '#245263'; ctx.beginPath(); ctx.arc(145 + i * 23, 31, 7, 0, GF.math.TAU); ctx.fill();
    }
    GF.Draw.text(ctx, this.progress + ' / 3', 31, 49, { size: 17, color: C.white, align: 'left' });

    GF.Draw.roundRect(ctx, 748, 15, 194, 47, 10, 'rgba(4,18,28,.80)');
    GF.Draw.text(ctx, 'SCORE', 764, 31, { size: 13, color: C.mint, align: 'left', weight: '800' });
    GF.Draw.text(ctx, String(game.score).padStart(3, '0'), 927, 43, { size: 25, color: C.white, align: 'right' });

    GF.Draw.roundRect(ctx, 286, 490, 388, 36, 10, 'rgba(4,18,28,.84)');
    GF.Draw.text(ctx, 'STORM PRESSURE', 300, 502, { size: 12, color: '#d9baff', align: 'left', weight: '800' });
    ctx.fillStyle = '#173744'; ctx.fillRect(300, 510, 350, 8);
    const col = this.pressure > 70 ? '#df85ef' : C.cyan;
    ctx.fillStyle = col; ctx.fillRect(300, 510, 350 * this.pressure / 100, 8);
    GF.Draw.text(ctx, Math.ceil(this.pressure) + '%', 659, 504, { size: 13, color: C.white, align: 'right', weight: '800' });
    GF.Draw.text(ctx, 'MOVE  •  RESONATE [SPACE / ENTER]', 480, 82, { size: 13, color: 'rgba(234,255,248,.72)', weight: '700' });
  }
};

game.add('play', play);
game.titleScreen({
  subtitle: 'Arrow keys / WASD to flow  •  SPACE / ENTER to resonate',
  onStart: () => game.go('play')
});
